import {session} from './auth.js';
import {scopedUrl,emitterContext} from './emitters.js';

export function createVerifactuViews({shell,heading,esc,icon,toast,modal,isAdmin,beforeAction,openInvoice}){
 const labels={pending:'Pendiente de envío',sending:'Enviando',accepted:'Aceptada en pruebas',accepted_errors:'Aceptada con errores',rejected:'Rechazada',network_error:'Conexión pendiente',blocked:'Requiere atención',verify_pending:'Verificando recepción'};
 const kinds={alta:'Alta',subsanacion:'Subsanación',anulacion:'Anulación de registro'};
 let timer;
 const badge=status=>`<span class="badge ${['accepted'].includes(status)?'':status==='accepted_errors'?'partial':'draft'}">${esc(labels[status]||status)}</span>`;
 async function request(path,data){const response=await fetch('/api/verifactu/'+path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:undefined);const value=await response.json();if(!response.ok)throw Error(value.error||'No se ha podido completar la operación de pruebas.');return value;}
 function controls(record){if(!emitterContext.active.active)return `<button class="btn ghost" data-vf-detail="${esc(record.id)}">Ver registro</button>`;return `<button class="btn ghost" data-vf-detail="${esc(record.id)}">Ver registro</button>${['pending','network_error','blocked','verify_pending'].includes(record.status)?`<button class="btn ghost" data-vf-action="retry" data-record="${esc(record.id)}">Reintentar</button>`:''}${['accepted_errors','rejected'].includes(record.status)&&record.kind!=='anulacion'?`<button class="btn ghost" data-vf-correct="${esc(record.id)}">Subsanar registro</button>`:''}${['accepted','accepted_errors','rejected'].includes(record.status)&&record.kind!=='anulacion'?`<button class="btn ghost" data-vf-cancel="${esc(record.id)}">Anular registro</button>`:''}`;}
 function rows(records){return records.length?`<div class="tablewrap"><table class="vf-record-table"><thead><tr><th>Factura de prueba</th><th>Registro</th><th>Estado AEAT</th><th>Detalle</th><th>Acciones</th></tr></thead><tbody>${records.map(r=>`<tr><td><button class="rowlink" data-vf-invoice="${esc(r.invoice_id)}">${esc(r.number)}</button><small class="cell-secondary">${esc(r.client)}</small></td><td>${esc(kinds[r.kind]||r.kind)}<small class="cell-secondary">${esc(new Date(r.created_at).toLocaleString('es-ES'))}</small></td><td>${badge(r.status)}</td><td>${esc(r.error||'—')}${r.code?`<small class="cell-secondary">Código ${esc(r.code)}</small>`:''}${r.csv?`<small class="cell-secondary">CSV ${esc(r.csv)}</small>`:''}</td><td><div class="actions">${controls(r)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>Todavía no hay registros de prueba</h3><p>En Nueva factura marca «VERI*FACTU · Pruebas AEAT» y revisa el documento antes de emitirlo.</p></div>`;}
 function configuration(config){const cert=config.certificate||{},identity=config.identity;
  return `<section class="panel formpanel vf-configuration"><h2>Configuración del emisor seleccionado</h2><p>Certificado propio para la empresa o autónomo activo. Conexión exclusiva al entorno oficial de pruebas.</p><form id="vf-config-form"><div class="fields">${session.user.isRoot?`<div class="field"><label for="vf-producer-name">Nombre del productor del programa</label><input id="vf-producer-name" name="producerName" value="${esc(identity.name)}" maxlength="120" required><small>Identidad de quien desarrolla el sistema, común a los emisores.</small></div><div class="field"><label for="vf-producer-nif">NIF del productor</label><input id="vf-producer-nif" name="producerNif" value="${esc(identity.nif)}" maxlength="9" required></div>`:''}<div class="field"><label for="vf-certificate">Certificado de este emisor (.p12 / .pfx)</label><input id="vf-certificate" type="file" accept=".p12,.pfx,application/x-pkcs12"><small>Máximo 100 KB. La clave privada se guarda cifrada en el servidor.</small></div><div class="field"><label for="vf-cert-password">Contraseña del archivo del certificado</label><input id="vf-cert-password" type="password" autocomplete="off"><small>Solo se usa para importar el archivo; no se conserva.</small></div></div>${cert.expires?`<div class="notice">Certificado de ${esc(cert.nif)} · válido hasta ${esc(new Date(cert.expires).toLocaleDateString('es-ES'))}.</div>`:'<p class="summary-note">Todavía no hay un certificado configurado para este emisor. Puedes emitir documentos de prueba que quedarán pendientes de envío.</p>'}<label class="check-label vf-auto"><input id="vf-auto-send" name="autoSend" type="checkbox" ${config.autoSend?'checked':''}>Enviar automáticamente a AEAT · solo pruebas</label><p class="summary-note">Si está desactivado, los documentos emitidos permanecen bloqueados y la cola queda en pausa. Una aceptación en pruebas no habilita el uso en producción.</p><div class="form-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit">Guardar configuración de pruebas</button><button class="btn" type="button" data-vf-check>Comprobar conexión</button>${cert.expires?'<button class="btn ghost" type="button" data-vf-remove-cert>Quitar certificado</button>':''}</div></form><p class="summary-note">Instalación ${esc(identity.installation)} · versión experimental.1 · ${config.dependencies?'Dependencias instaladas':'Pendiente de instalar dependencias en el servidor'}</p></section>`;
 }
 async function refreshRows(){const element=document.querySelector('#vf-record-rows');if(!element)return;try{const data=await request('records');if(element.isConnected)element.innerHTML=rows(data.records);}catch(error){toast(error.message);}timer=setTimeout(refreshRows,5000);}
 async function render(){clearTimeout(timer);try{const [config,data]=await Promise.all([request('config'),request('records')]);shell(heading('VERI*FACTU · pruebas','Conexión experimental propia con la AEAT para el emisor seleccionado.')+`<div class="notice vf-warning"><strong>Entorno oficial de pruebas</strong><p>Los documentos de este apartado están separados de la facturación habitual y no tienen validez fiscal.</p><p>Emisiones inmodificables · ${config.autoSend?'envío automático activado':'envíos en pausa'}.</p></div><section class="panel" id="vf-record-rows">${rows(data.records)}</section>${isAdmin()?configuration(config):'<p class="summary-note">Un administrador configura el certificado y los envíos de este emisor. Solo se muestran tus registros.</p>'}`,'VERI*FACTU · pruebas');timer=setTimeout(refreshRows,5000);}catch(error){toast(error.message);}}
 async function loadPanel(invoice){clearTimeout(timer);const element=document.querySelector('#vf-invoice-status');if(!element)return;try{const config=await request('config'),data=await request('records');const related=data.records.filter(r=>r.invoice_id===invoice.id);if(!element.isConnected)return;element.innerHTML=`<strong>VERI*FACTU · Pruebas AEAT</strong><p>Documento bloqueado desde su emisión.</p>${!config.autoSend?'<p>Envíos en pausa. Configura el certificado y el envío automático para comunicarlo.</p>':''}${related.map(record=>`<div class="vf-panel-record">${badge(record.status)}<small>${esc(kinds[record.kind])}</small>${record.error?`<p>${esc(record.error)}</p>`:''}<div class="actions">${controls(record)}</div></div>`).join('')}`;timer=setTimeout(()=>loadPanel(invoice),5000);}catch(error){if(element.isConnected)element.textContent=error.message;}}
 function dialog(content){modal.className='finance-modal';modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button>${content}`;if(!modal.open)modal.showModal();}
 document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.vfInvoice){await beforeAction();openInvoice(button.dataset.vfInvoice);return;}
  if(button.dataset.vfDetail){const value=await request('records/'+encodeURIComponent(button.dataset.vfDetail));const r=value.record;dialog(`<h2>Registro de pruebas AEAT</h2><p>${badge(r.status)} · ${esc(kinds[r.kind])}</p><p class="vf-hash">Huella ${esc(r.hash)}</p><p>${esc(r.error||'Sin incidencias comunicadas.')}${r.csv?'<br>CSV '+esc(r.csv):''}</p><a class="btn" href="${scopedUrl('/api/verifactu/records/'+encodeURIComponent(r.id)+'/xml')}" download>Descargar XML enviado</a><h3>Intentos de comunicación</h3>${value.attempts.map(a=>`<p>${esc(new Date(a.created_at).toLocaleString('es-ES'))} · ${esc(labels[a.status]||a.status)}<br>${esc(a.error)}</p>`).join('')||'<p>Todavía no hay intentos de envío.</p>'}`);return;}
  if(button.dataset.vfAction){button.disabled=true;await beforeAction();await request('action',{recordId:button.dataset.record,action:button.dataset.vfAction});toast('Registro pendiente de reintento. El envío automático debe estar activado.');return;}
  if(button.dataset.vfCorrect||button.dataset.vfCancel){const cancel=!!button.dataset.vfCancel,recordId=button.dataset.vfCancel||button.dataset.vfCorrect;dialog(`<h2>${cancel?'Anular registro de prueba':'Subsanar registro de prueba'}</h2><p>${cancel?'Se añadirá un registro de anulación, conservando la factura y su alta.':'Corrige los datos del registro que se comunicaron incorrectamente. Si la propia factura está mal, utiliza una factura rectificativa. El original se conserva.'}</p><form id="vf-action-form" data-record="${esc(recordId)}" data-kind="${cancel?'anular':'subsanar'}"><div class="fields">${cancel?'<div class="field full"><label for="vf-reason">Motivo de anulación</label><textarea id="vf-reason" name="reason" required minlength="3" maxlength="500"></textarea></div>':'<div class="field"><label for="vf-recipient-name">Nombre del destinatario en el registro</label><input id="vf-recipient-name" name="recipientName" maxlength="120"></div><div class="field"><label for="vf-recipient-nif">NIF del destinatario en el registro</label><input id="vf-recipient-nif" name="recipientNif" maxlength="9"></div><div class="field full"><label for="vf-description">Descripción del registro</label><textarea id="vf-description" name="description" maxlength="500"></textarea><small>Deja vacíos los campos que ya sean correctos.</small></div>'}</div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Crear ${cancel?'anulación':'subsanación'} de prueba</button></form>`);return;}
  if(button.hasAttribute('data-vf-check')){button.disabled=true;await beforeAction();await request('check',{});toast('Conexión confirmada con el entorno oficial de pruebas.');return;}
  if(button.hasAttribute('data-vf-remove-cert')){button.disabled=true;await beforeAction();await request('config',{removeCertificate:true,autoSend:false});await render();toast('Certificado retirado; envíos en pausa.');}
 }catch(error){toast(error.message);}finally{if(button.isConnected&&(button.hasAttribute('data-vf-check')||button.dataset.vfAction||button.hasAttribute('data-vf-remove-cert')))button.disabled=false;}});
 document.addEventListener('submit',async event=>{const form=event.target;if(!['vf-config-form','vf-action-form'].includes(form.id))return;event.preventDefault();const button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';try{await beforeAction();
  if(form.id==='vf-config-form'){const fields=Object.fromEntries(new FormData(form)),file=form.querySelector('#vf-certificate').files[0];const payload={...fields,autoSend:form.querySelector('#vf-auto-send').checked};if(file){if(file.size>100000)throw Error('El certificado supera 100 KB.');payload.certificate=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('No se puede leer el certificado.'));reader.readAsDataURL(file);});payload.password=form.querySelector('#vf-cert-password').value;}await request('config',payload);form.querySelector('#vf-cert-password').value='';await render();toast('Configuración de pruebas guardada.');}
  else{await request('action',{recordId:form.dataset.record,action:form.dataset.kind,details:Object.fromEntries(new FormData(form))});modal.close();toast('Nuevo registro de prueba creado. El original permanece conservado.');await refreshRows();}
 }catch(exc){error.textContent=exc.message;button.disabled=false;}});
 return {render,loadPanel};
}
